def build_preprocessor(numeric_features, categorical_features, scaler=True):
    """
    数値とカテゴリ列をまとめて前処理する ColumnTransformer を構築する。
    - 数値列: 標準化 or そのまま通す
    - カテゴリ列: One-Hotエンコード（未知カテゴリ無視）
    """
    if scaler:
        numeric_transformer = sklearn.pipeline.Pipeline(steps=[('scaler', sklearn.preprocessing.StandardScaler())])
    else:
        numeric_transformer = sklearn.pipeline.Pipeline(steps=[('identity', type())])
    try:
        categorical_transformer = sklearn.preprocessing.OneHotEncoder(handle_unknown='ignore', sparse_output=False)
    except TypeError:
        categorical_transformer = sklearn.preprocessing.OneHotEncoder(handle_unknown='ignore', sparse=False)
    preprocessor = sklearn.compose.ColumnTransformer(transformers=[('num', numeric_transformer, numeric_features), ('cat', categorical_transformer, categorical_features)], remainder='drop')
    return preprocessor

